 */
public final class PropunereAI {

    private PropunereAI() {
    }

    /** Transportul cererii: primește corpul JSON (doar {@link #CAMPURI_CERERE}) și întoarce răspunsul JSON. */
    public interface Transport {
        String cere(String corpJson) throws IOException;
    }

    /** Cârligul testelor (vizibil doar în pachet, implicit {@code null}; 0 atribuiri în {@code src/}). */
    static Transport transportTest;

