    public static final List<String> CAMPURI_CERERE = List.of("cod", "denumire", "camp", "valoare", "instructiune");

    /** Rezultatul: lotul propus (rândurile refuzate poartă motivul) sau refuzul tradus al cererii ({@code lot} = {@code null}). */
    public record Propunere(ModificareInMasa.Lot lot, String refuz) {
        public boolean refuzata() {
            return refuz != null;
        }
    }

    /** Transportul ales de setarea firmei: {@code DEMO} ⇒ cârligul testului sau {@link #DEMO}; altfel {@code null} (0 cereri). */
    static Transport transport(String setare) {
        if (!ParametriT352.AI_DEMO.equals(setare))
            return null;
        return transportTest != null ? transportTest : DEMO;
    }

    /**
     * Propunerea pentru domeniu și instrucțiune: dreptul ÎNAINTEA transportului (și înaintea citirii setării); setarea transportului
     * pe firmă; apoi {@link #propuneDin}; propunerea reușită lasă un rând de jurnal {@code PROPUNERE_AI}; 0 scrieri în fișă.
     */
    public static Propunere propune(Properties ctx, ModificareInMasa.Domeniu d, String instructiune, ModificareInMasa.Surse s) {
        if (d == null || d.client() <= 0)
            throw new IllegalStateException(Etichete.t("t352.refuz.firma"));
        String drept = ModOperatie.motivFaraDrept(ctx, FisaCanalProces.VALUE, FisaCanalProces.SUPRASCRIU);
        String setare = drept != null ? null : ParametriT352.valori(d.client()).get(ParametriT352.AI_TRANSPORT);
        Propunere p = propuneDin(drept, setare, d, instructiune, s);
        if (!p.refuzata())
            jurnal(ctx, d, DomeniiT352.PROPUNERE_AI, DomeniiT22.MODIFICAT_INAINTE, p.lot().amprenta());
        return p;
    }

    /**
