     * Bucla lotului (instanța unică, §C C.10): {@link #inainteDeTrimitere} O DATĂ, înaintea primei cereri (cererile refuzate:
     * 0 trimiteri, 0 {@link #dupaTrimitere}, {@code refuzata} cu cheia); apoi pentru fiecare cerere {@link #trimiteCererea} →
     * {@code aplica} (rândurile) → {@link #dupaTrimitere} cu {@code r.codHttp()} / {@code r.codEroare()}; o excepție din trimitere
     * ⇒ {@code dupaTrimitere(…, 0, <mesajul>, …)}, apoi excepția iese (nu se înghite).
     */
    Rezumat trimiteLot(Properties ctx, int client, int sursaSiteId, String canal, List<ApiSiteProduse.Cerere> lot,
            Integer adSchedulerId, int adUserId, String operatie, int pinstance, String trx,
            BiConsumer<ApiSiteProduse.Cerere, AdaptorPlatforma.RezultatScriere> aplica, BiConsumer<ApiSiteProduse.Cerere, String> refuzata) {
        if (lot.isEmpty())
            return new Rezumat(0, 0, 0);
        Map<ApiSiteProduse.Cerere, String> refuz = inainteDeTrimitere(ctx, client, sursaSiteId, canal, lot, adSchedulerId, adUserId,
                operatie, trx);
        int trimise = 0, reusite = 0, esuate = 0;
        for (ApiSiteProduse.Cerere c : lot) {
            String cheie = refuz == null ? null : refuz.get(c);
            if (cheie != null) {
                refuzata.accept(c, cheie);
                continue;
            }
            AdaptorPlatforma.RezultatScriere r;
            try {
                r = trimiteCererea(ctx, client, sursaSiteId, c, pinstance, trx);
            } catch (RuntimeException e) {
                dupaTrimitere(ctx, client, sursaSiteId, canal, c, 0, e.getMessage(), trx);
                throw e;
            }
            trimise++;
            if (r.codHttp() >= 200 && r.codHttp() < 300)
                reusite++;
            else
                esuate++;
            aplica.accept(c, r);
            dupaTrimitere(ctx, client, sursaSiteId, canal, c, r.codHttp(), r.codEroare(), trx);
        }
        return new Rezumat(trimise, reusite, esuate);
    }

