def create_order(body: dict, request: Request, db: Session = Depends(get_db)):
    """Comandă client (is_sotrx=true) sau furnizor (false), cu linii. 1:1 iDempiere."""
    ctx, c, _ = _ctx_client(request, db)
    ep = "POST /operare/orders"
    key, prev = _idem(request, db, ctx, ep)
    if prev:
        return prev
    if not hasattr(c, "create_order"):
        raise EvaError("EVA-OP_UNSUPPORTED", "comenzile necesită client REST (firmă cu client dedicat)", 424)
    # AUTO-REZOLVARE: produsele trebuie să aibă preț pe lista de prețuri (altfel C_OrderLine eșuează)
    from ..idempiere import adconfig
    _cid = int(ctx.get("ad_client_id") or 11)
    for _ln in body.get("lines", []):
