        lines=body["lines"], date_ordered=body.get("date_ordered", ""),
        doctype_id=body.get("doctype_id"), description=body.get("description", ""),
        complete=bool(body.get("complete", False)))
    _audit(db, ctx, "operare.order.create", "C_Order", res.get("order_id"), res)
    if key:
        idempotency.store(db, ctx["tenant_cui"], ep, key, 201, res)
    db.commit()
    return res


@router.post("/operare/orders/{order_id}/doc-action")
def order_doc_action(order_id: int, body: dict, request: Request, db: Session = Depends(get_db)):
    """Acțiune document pe comandă (CO/CL/VO/RE/RC) — prin doc-action iDempiere, NU PUT pe DocStatus."""
    ctx, c, _ = _ctx_client(request, db)
    action = (body.get("action") or "CO").upper()
    if action not in perms.DOC_ACTIONS:
