    /**
     * T22 (spec 74 §6.1, cu decizia 71 «două marcaje» și semnătura cerută în 71 pentru T35) — selecția surselor (pură):
     * {@code Ce=COMENZI} cu {@code idSursa > 0} ⇒ EXACT acea sursă, dacă e în {@code active}, are {@code EVA_VanzariOnline='Y'}
     * (altfel {@code vanzari.preluare.sursa_oprita}, 74m), are {@code EVA_SursaProprie='Y'}
     * și trece filtrul suplimentar, altfel {@link IllegalStateException} cu cheia {@code vanzari.preluare.sursa_neproprie};
     * {@code Ce=COMENZI} fără sursă ⇒ sursele active cu {@code EVA_VanzariOnline='Y'} și {@code EVA_SursaProprie='Y'} care
     * trec filtrul, în ordinea {@code EVA_SursaSite_ID} (listă goală = mesajul {@code vanzari.preluare.fara_surse_proprii},
     * 0 cereri); orice alt {@code Ce} ⇒ {@code null} = calea T20 neschimbată. {@code EVA_ScrierePermisa} NU intră aici
     * (e doar poarta scrierii). Legarea în {@code doIt} = B-BE-1.
     */
    static List<SursaSiteConfig.SursaT22> surse(String ce, int idSursa, List<SursaSiteConfig.SursaT22> active,
            java.util.function.Predicate<SursaSiteConfig.SursaT22> filtruSuplimentar) {
        if (!"COMENZI".equals(ce))
            return null;
        if (idSursa > 0) {
            for (SursaSiteConfig.SursaT22 s : active)
                if (s.id() == idSursa && !s.vanzariOnline())   // 74 §6.1 (a) / 74m: sursa aleasă cu «Vânzări online» = Nu ⇒ exclusă
                    throw new IllegalStateException(Etichete.t("vanzari.preluare.sursa_oprita"));
            for (SursaSiteConfig.SursaT22 s : active)
                if (s.id() == idSursa && s.sursaProprie() && filtruSuplimentar.test(s))
                    return List.of(s);
            throw new IllegalStateException(Etichete.t("vanzari.preluare.sursa_neproprie"));
        }
        List<SursaSiteConfig.SursaT22> l = new ArrayList<>();
        for (SursaSiteConfig.SursaT22 s : active)
            if (s.vanzariOnline() && s.sursaProprie() && filtruSuplimentar.test(s))
                l.add(s);
        l.sort(java.util.Comparator.comparingInt(SursaSiteConfig.SursaT22::id));
