    /** Ferestrele [de, pana] câte {@code API_FEREASTRA_ZILE} zile (pur — testat). */
    static List<Timestamp[]> ferestre(Timestamp de, Timestamp pana, int zile) {
        List<Timestamp[]> l = new ArrayList<>();
        java.time.LocalDate a = de.toLocalDateTime().toLocalDate(), z = pana.toLocalDateTime().toLocalDate().plusDays(1);
        while (a.isBefore(z)) {
            java.time.LocalDate b = a.plusDays(zile).isAfter(z) ? z : a.plusDays(zile);
            l.add(new Timestamp[]{Timestamp.valueOf(a.atStartOfDay()), Timestamp.valueOf(b.atStartOfDay())});
            a = b;
        }
        return l;
    }

    /** Comenzile, pe ferestre; detaliul doar pentru comenzile noi / schimbate ale conturilor firmei. Întoarce max(updated_at). */
    private Timestamp comenzi(Properties ctx, int client, AdaptorPlatforma s, SursaSiteConfig.Config cfg, boolean sitePropriu, Contor k)
            throws Exception {
        Timestamp maxAct = cfg.ultimaActualizare;
        int faraCont = k.comenziFaraCont;
        long pauza = MotorCorelare.prag("API_PAUZA_MS").longValue();
        // T35 L5 (08-L5 §6): tipul platformei fișei (registrul) și moneda firmei (schema contabilă principală) pentru filtrul de monedă
        PlatformeVanzari.DescrierePlatforma platforma = PlatformeVanzari.descriere(s.cod());
        String tipPlatforma = platforma == null ? "" : platforma.tip();
        String monedaFirmei = TIP_FILTRU_MONEDA.contains(tipPlatforma) ? monedaFirmei(client, get_TrxName()) : "";
        int altaMonedaInainte = k.comenziAltaMoneda;
        for (Timestamp[] f : ferestre(de, pana, MotorCorelare.prag("API_FEREASTRA_ZILE").intValue())) {
            if (SursaSiteConfig.oprireCeruta(client)) {
                k.oprit = true;
                break;
            }
            // B2b-1: lista pe fereastră se cere ÎNTREAGĂ (fără updated_since — un cursor global ar pierde comenzile nemodificate
            // ale unei ferestre mai vechi preluate ulterior); economia e pe detaliu: comparația locală cu EVA_ActualizatSursa.
            for (SursaCesiro1.ComandaSursa c0 : s.comenzi(f[0], f[1], null)) {
                SursaCesiro1.ComandaSursa c = aFirmei(c0, cfg, sitePropriu, k);   // API-ul nu filtrează pe cont: filtrul e local
                if (c == null)
                    continue;
                if (sareMoneda(tipPlatforma, c.moneda(), monedaFirmei)) {   // T35 L5 (08-L5 §6): altă monedă pe consolidator / marketplace
                    k.comenziAltaMoneda++;
                    continue;
                }
                if (c.actualizat() != null && (maxAct == null || c.actualizat().after(maxAct)))
                    maxAct = c.actualizat();
                PO p = new Query(ctx, CorelareTabele.COMANDA, "AD_Client_ID=? AND EVA_Sursa=? AND EVA_IdExtern=?", get_TrxName())
                        .setParameters(client, codFisa, c.id()).first();
                if (!deActualizat(c, p == null ? null : (Timestamp) p.get_Value("EVA_ActualizatSursa"))) {
                    k.comenziNeschimbate++;
                    continue;
                }
                SursaCesiro1.Detaliu d = c.inline();
                if (d == null) {                                // detaliul DOAR dacă lista nu l-a adus
                    if (SursaSiteConfig.oprireCeruta(client)) {
                        k.oprit = true;
                        break;
                    }
                    if (pauza > 0 && !s.cereri().isEmpty())
                        Thread.sleep(pauza);
                    d = s.detaliu(c.id());
                }
                int idEva = comanda(ctx, client, p, c, d.facturi(), k);
                for (SursaCesiro1.ExpediereSursa e : d.expedieri())
                    expediere(ctx, client, e.id(), idEva, e.furnizor(), e.curier(), e.awb(), e.stareColet(), e.ramburs(),
                            e.stareRamburs(), e.emis(), e.livrat(), e.cost(), e.monedaCost(), e.actualizat(), e.sumaVirata(),
                            e.comision(), e.borderou(), k);
                if (d.expedieri().isEmpty() && !c.tracking().isBlank())      // AWB pe comandă fără rând în shipments (§4.2)
                    expediere(ctx, client, "ORD:" + c.id(), idEva, "", "", c.tracking(), "", null, "", null, null, null, "",
