                    x[0] = codFisa;
                    System.arraycopy(m, 1, x, 1, m.length - 1);
                    addLog(Etichete.t((String) m[0], x));
    }

    /** «a;b» din numerele de factură, fără dubluri, tăiat la 255 pe graniță de număr. */
    static String numere(List<String> l) {
        StringBuilder sb = new StringBuilder();
        java.util.Set<String> vazute = new java.util.LinkedHashSet<>();
        for (String x : l) {
            if (!MotorCorelare.esteNrFactura(x) || !vazute.add(x.strip()))
                continue;
            String y = x.strip().replace(';', ',');
            if (sb.length() + y.length() + 1 > 255)
                break;
            if (sb.length() > 0)
                sb.append(';');
            sb.append(y);
        }
        return sb.toString();
    }

