    private List<RandLinie> linii(int id) throws SQLException {
        List<RandLinie> l = new ArrayList<>();
        try (PreparedStatement ps = DB.prepareStatement("SELECT eva_comandasitelinie_id, eva_nrlinie, eva_sku, eva_ean, eva_cantitate, eva_pretbrut,"
                + " eva_pretbrutvaluta, eva_moneda, eva_cotatva, eva_totallinie, coalesce(m_product_id,0), eva_starelinie, c_order_id IS NOT NULL,"
