def _order_view(row: dict[str, Any], items: list[dict[str, Any]], tenant_slug: str) -> dict[str, Any]:
    order = _clean(row)
    order["tenant"] = tenant_slug
    order["items"] = items
    net = sum(_money(i.get("line_total_net_ron")) for i in items)
    vat = sum(_money(i.get("line_vat_ron")) for i in items)
    order["items_summary"] = {"lines": len(items), "qty": sum(int(i.get("qty") or 0) for i in items),
                              "net_ron": float(net), "vat_ron": float(vat),
                              "gross_ron": float(sum(_money(i.get("line_total_gross_ron")) for i in items))}
